    99→    @IsTest
   100→    static void testGetWorkItemsForProject() {
   101→        Project__c project = [SELECT Id FROM Project__c LIMIT 1];
   102→
   103→        Test.startTest();
   104→        WorkItemController.ProjectDataWrapper result = WorkItemController.getWorkItemsForProject(project.Id, 3);
   105→        Test.stopTest();
   106→
   107→        // Verify project data
   108→        System.assertNotEquals(null, result, 'Should return ProjectDataWrapper');
   109→        System.assertEquals(project.Id, result.projectId, 'Should return correct project ID');
   110→        System.assertNotEquals(null, result.projectStartDate, 'Should return project start date');
   111→        System.assertNotEquals(null, result.projectDueDate, 'Should return project due date');
   112→
   113→        // Verify root level items
   114→        System.assertEquals(5, result.workItems.size(), 'Should return 5 root Work Items');
   115→
   116→        // Verify first level children
   117→        WorkItemController.WorkItemWrapper firstMilestone = result.workItems[0];
   118→        System.assertEquals(2, firstMilestone.children.size(), 'Each milestone should have 2 deliverables');
   119→
   120→        // Verify second level children
   121→        WorkItemController.WorkItemWrapper firstDeliverable = firstMilestone.children[0];
   122→        System.assertEquals(3, firstDeliverable.children.size(), 'Each deliverable should have 3 tasks');
   123→
   124→        // Verify depth tracking
   125→        System.assertEquals(0, firstMilestone.depth, 'Root item should have depth 0');
   126→        System.assertEquals(1, firstDeliverable.depth, 'Level 1 item should have depth 1');
   127→        System.assertEquals(2, firstDeliverable.children[0].depth, 'Level 2 item should have depth 2');
   128→
   129→        // Verify progress calculation
   130→        System.assert(firstDeliverable.progress > 0, 'Progress should be calculated for items with actual hours');
   131→
   132→        // Verify wrapper fields populated correctly
   133→        System.assertNotEquals(null, firstMilestone.id, 'Wrapper should have ID');
   134→        System.assertNotEquals(null, firstMilestone.name, 'Wrapper should have name');
   135→        System.assertNotEquals(null, firstMilestone.status, 'Wrapper should have status');
   136→        System.assertNotEquals(null, firstMilestone.templateId, 'Wrapper should have template ID');
   137→    }
