   215→    @IsTest
   216→    static void testIsAtRisk() {
   217→        // Test overdue item
   218→        Boolean atRisk = WorkItemService.isAtRisk(Date.today().addDays(-1), 50);
   219→        System.assertEquals(true, atRisk, 'Overdue item should be at risk');
   220→
   221→        // Test item due soon with low progress
