   223→        System.assertEquals(true, atRisk, 'Item due within 3 days with <75% progress should be at risk');
   224→
   225→        // Test item due soon with high progress
   226→        atRisk = WorkItemService.isAtRisk(Date.today().addDays(2), 80);
   227→        System.assertEquals(false, atRisk, 'Item due within 3 days with >=75% progress should not be at risk');
   228→
   229→        // Test item not due soon
   230→        atRisk = WorkItemService.isAtRisk(Date.today().addDays(10), 20);
