/**
 * @description Test class for WorkItemController and WorkItemService
 * Tests hierarchical querying, wrapper construction, and bulk operations
 *
 * @group Tests
 * @date 2025-10-06
 */
@IsTest
private class WorkItemControllerTest {
    @TestSetup
    static void setup() {
        // Create Project Template
        Project_Template__c projectTemplate = new Project_Template__c(Name = 'Test Project Template', Description__c = 'Test template for projects');
        insert as user projectTemplate;

        // Create Work Item Template
        Work_Item_Template__c workItemTemplate = new Work_Item_Template__c(Name = 'Test Work Item Template', Description__c = 'Test template for work items');
        insert as user workItemTemplate;

        // Create Test Project
        Project__c project = new Project__c(
            Name = 'Test Project',
            Status__c = 'Active',
            Start_Date__c = Date.today(),
            End_Date__c = Date.today().addDays(90),
            Project_Manager__c = UserInfo.getUserId(),
            Project_Template__c = projectTemplate.Id
        );
        insert as user project;

        // Create hierarchical Work Items (3 levels deep)
        List<Work_Item__c> workItems = new List<Work_Item__c>();

        // Level 0: Root Work Items (Milestones)
        for (Integer i = 0; i < 5; i++) {
            workItems.add(
                new Work_Item__c(
                    Work_Item_Name__c = 'Milestone ' + i,
                    Project__c = project.Id,
                    Work_Item_Template__c = workItemTemplate.Id,
                    Status__c = 'Not Started',
                    Start_Date__c = Date.today().addDays(i * 10),
                    Due_Date__c = Date.today().addDays((i + 1) * 10),
                    Estimated_Hours__c = 100,
                    Actual_Hours__c = 0,
                    Summary__c = 'Test milestone ' + i
                )
            );
        }
        insert as user workItems;

        // Level 1: Child Work Items (Deliverables) - 2 per milestone
        List<Work_Item__c> level1Items = new List<Work_Item__c>();
        for (Work_Item__c parent : workItems) {
            for (Integer j = 0; j < 2; j++) {
                level1Items.add(
                    new Work_Item__c(
                        Work_Item_Name__c = parent.Work_Item_Name__c + ' - Deliverable ' + j,
                        Project__c = project.Id,
                        Work_Item_Template__c = workItemTemplate.Id,
                        Parent_Work_Item__c = parent.Id,
                        Status__c = 'In Progress',
                        Start_Date__c = parent.Start_Date__c,
                        Due_Date__c = parent.Due_Date__c,
                        Estimated_Hours__c = 40,
                        Actual_Hours__c = 20,
                        Summary__c = 'Test deliverable for ' + parent.Work_Item_Name__c
                    )
                );
            }
        }
        insert as user level1Items;

        // Level 2: Grandchild Work Items (Tasks) - 3 per deliverable
        List<Work_Item__c> level2Items = new List<Work_Item__c>();
        for (Work_Item__c parent : level1Items) {
            for (Integer k = 0; k < 3; k++) {
                level2Items.add(
                    new Work_Item__c(
                        Work_Item_Name__c = parent.Work_Item_Name__c + ' - Task ' + k,
                        Project__c = project.Id,
                        Work_Item_Template__c = workItemTemplate.Id,
                        Parent_Work_Item__c = parent.Id,
                        Status__c = k == 0 ? 'Complete' : 'Not Started',
                        Start_Date__c = parent.Start_Date__c,
                        Due_Date__c = parent.Due_Date__c,
                        Estimated_Hours__c = 10,
                        Actual_Hours__c = k == 0 ? 10 : 0,
                        Summary__c = 'Test task for ' + parent.Work_Item_Name__c
                    )
                );
            }
        }
        insert as user level2Items;

        // Total Work Items: 5 + (5*2) + (5*2*3) = 5 + 10 + 30 = 45 items
    }

    @IsTest
    static void testGetWorkItemsForProject() {
        Project__c project = [SELECT Id FROM Project__c LIMIT 1];

        Test.startTest();
        WorkItemController.ProjectDataWrapper result = WorkItemController.getWorkItemsForProject(project.Id, 3);
        Test.stopTest();

        // Verify project data
        System.assertNotEquals(null, result, 'Should return ProjectDataWrapper');
        System.assertEquals(project.Id, result.projectId, 'Should return correct project ID');
        System.assertNotEquals(null, result.projectStartDate, 'Should return project start date');
        System.assertNotEquals(null, result.projectDueDate, 'Should return project due date');

        // Verify root level items
        System.assertEquals(5, result.workItems.size(), 'Should return 5 root Work Items');

        // Verify first level children
        WorkItemController.WorkItemWrapper firstMilestone = result.workItems[0];
        System.assertEquals(2, firstMilestone.children.size(), 'Each milestone should have 2 deliverables');

        // Verify second level children
        WorkItemController.WorkItemWrapper firstDeliverable = firstMilestone.children[0];
        System.assertEquals(3, firstDeliverable.children.size(), 'Each deliverable should have 3 tasks');

        // Verify depth tracking
        System.assertEquals(0, firstMilestone.depth, 'Root item should have depth 0');
        System.assertEquals(1, firstDeliverable.depth, 'Level 1 item should have depth 1');
        System.assertEquals(2, firstDeliverable.children[0].depth, 'Level 2 item should have depth 2');

        // Verify progress calculation
        System.assert(firstDeliverable.progress > 0, 'Progress should be calculated for items with actual hours');

        // Verify wrapper fields populated correctly
        System.assertNotEquals(null, firstMilestone.id, 'Wrapper should have ID');
        System.assertNotEquals(null, firstMilestone.name, 'Wrapper should have name');
        System.assertNotEquals(null, firstMilestone.status, 'Wrapper should have status');
        System.assertNotEquals(null, firstMilestone.templateId, 'Wrapper should have template ID');
    }

    @IsTest
    static void testGetWorkItemsForProjectWithLimitedDepth() {
        Project__c project = [SELECT Id FROM Project__c LIMIT 1];

        Test.startTest();
        WorkItemController.ProjectDataWrapper result = WorkItemController.getWorkItemsForProject(project.Id, 1);
        Test.stopTest();

        // Verify only 1 level of children retrieved
        WorkItemController.WorkItemWrapper firstMilestone = result.workItems[0];
        System.assertEquals(2, firstMilestone.children.size(), 'Should retrieve first level children');
        System.assertEquals(0, firstMilestone.children[0].children.size(), 'Should not retrieve second level children');
    }

    @IsTest
    static void testGetWorkItemWithChildren() {
        Work_Item__c rootItem = [
            SELECT Id
            FROM Work_Item__c
            WHERE Parent_Work_Item__c = NULL
            LIMIT 1
