    22→            Name = 'Test Project',
    23→            Status__c = 'Active',
    24→            Start_Date__c = Date.today(),
    25→            End_Date__c = Date.today().addDays(90),
    26→            Project_Manager__c = UserInfo.getUserId(),
    27→            Project_Template__c = projectTemplate.Id
    28→        );
    29→        insert as user project;
    30→
    31→        // Create hierarchical Work Items (3 levels deep)
    32→        List<Work_Item__c> workItems = new List<Work_Item__c>();
    33→
    34→        // Level 0: Root Work Items (Milestones)
    35→        for (Integer i = 0; i < 5; i++) {
    36→            workItems.add(
    37→                new Work_Item__c(
    38→                    Work_Item_Name__c = 'Milestone ' + i,
    39→                    Project__c = project.Id,
    40→                    Work_Item_Template__c = workItemTemplate.Id,
    41→                    Status__c = 'Not Started',
    42→                    Start_Date__c = Date.today().addDays(i * 10),
    43→                    Due_Date__c = Date.today().addDays((i + 1) * 10),
    44→                    Estimated_Hours__c = 100,
    45→                    Actual_Hours__c = 0,
    46→                    Summary__c = 'Test milestone ' + i
    47→                )
    48→            );
    49→        }
    50→        insert as user workItems;
    51→
    52→        // Level 1: Child Work Items (Deliverables) - 2 per milestone
    53→        List<Work_Item__c> level1Items = new List<Work_Item__c>();
    54→        for (Work_Item__c parent : workItems) {
    55→            for (Integer j = 0; j < 2; j++) {
    56→                level1Items.add(
    57→                    new Work_Item__c(
    58→                        Work_Item_Name__c = parent.Work_Item_Name__c + ' - Deliverable ' + j,
    59→                        Project__c = project.Id,
    60→                        Work_Item_Template__c = workItemTemplate.Id,
    61→                        Parent_Work_Item__c = parent.Id,
    62→                        Status__c = 'In Progress',
    63→                        Start_Date__c = parent.Start_Date__c,
    64→                        Due_Date__c = parent.Due_Date__c,
    65→                        Estimated_Hours__c = 40,
    66→                        Actual_Hours__c = 20,
    67→                        Summary__c = 'Test deliverable for ' + parent.Work_Item_Name__c
    68→                    )
    69→                );
    70→            }
    71→        }
    72→        insert as user level1Items;
    73→
    74→        // Level 2: Grandchild Work Items (Tasks) - 3 per deliverable
    75→        List<Work_Item__c> level2Items = new List<Work_Item__c>();
    76→        for (Work_Item__c parent : level1Items) {
    77→            for (Integer k = 0; k < 3; k++) {
    78→                level2Items.add(
    79→                    new Work_Item__c(
    80→                        Work_Item_Name__c = parent.Work_Item_Name__c + ' - Task ' + k,
    81→                        Project__c = project.Id,
    82→                        Work_Item_Template__c = workItemTemplate.Id,
    83→                        Parent_Work_Item__c = parent.Id,
    84→                        Status__c = k == 0 ? 'Complete' : 'Not Started',
    85→                        Start_Date__c = parent.Start_Date__c,
    86→                        Due_Date__c = parent.Due_Date__c,
    87→                        Estimated_Hours__c = 10,
    88→                        Actual_Hours__c = k == 0 ? 10 : 0,
    89→                        Summary__c = 'Test task for ' + parent.Work_Item_Name__c
    90→                    )
    91→                );
    92→            }
    93→        }
    94→        insert as user level2Items;
    95→
    96→        // Total Work Items: 5 + (5*2) + (5*2*3) = 5 + 10 + 30 = 45 items
    97→    }
