    @IsTest
    static void testReparentWorkItemDirectlyOntoParent() {
        // Get two milestones
        Work_Item__c sourceParent = [SELECT Id, Work_Item_Template__c FROM Work_Item__c WHERE Work_Item_Name__c = 'Milestone 0' LIMIT 1];
        Work_Item__c targetParent = [SELECT Id, Work_Item_Template__c, Parent_Work_Item__c FROM Work_Item__c WHERE Work_Item_Name__c = 'Milestone 1' LIMIT 1];

        List<Work_Item__c> deliverables1 = [
            SELECT Id, Parent_Work_Item__c, Work_Item_Template__c
            FROM Work_Item__c
            WHERE Parent_Work_Item__c = :sourceParent.Id
            ORDER BY Work_Item_Name__c
        ];

        Work_Item__c draggedItem = deliverables1[0];

        // Create Allowed_Child_Type__c to allow draggedItem under milestone
        Allowed_Child_Type__c allowedChild = new Allowed_Child_Type__c(
            Parent_Work_Item_Template__c = targetParent.Work_Item_Template__c,
            Child_Work_Item_Template__c = draggedItem.Work_Item_Template__c
        );
        insert as user allowedChild;

        Test.startTest();
        // Drop draggedItem directly onto milestone2 (to make it a child of milestone2)
        // When targetItemId == targetParentId, it means dropping onto parent itself
        WorkItemController.moveWorkItem(draggedItem.Id, targetParent.Id);
        Test.stopTest();

        // Verify the draggedItem was moved
        Work_Item__c movedDeliverable = [
            SELECT Id, Parent_Work_Item__c
            FROM Work_Item__c
            WHERE Id = :draggedItem.Id
        ];

        System.assertEquals(targetParent.Id, movedDeliverable.Parent_Work_Item__c, 'Deliverable should be reparented to Milestone 2');

        // Verify counts
        Integer count1 = [SELECT COUNT() FROM Work_Item__c WHERE Parent_Work_Item__c = :sourceParent.Id];
        Integer count2 = [SELECT COUNT() FROM Work_Item__c WHERE Parent_Work_Item__c = :targetParent.Id];

        System.assertEquals(1, count1, 'Milestone 1 should now have 1 draggedItem');
        System.assertEquals(3, count2, 'Milestone 2 should now have 3 deliverables');
    }
}

