        Test.stopTest();

        // History may or may not exist depending on tracking settings
        System.assertNotEquals(null, history, 'Should return history list (may be empty)');
    }

    @IsTest
    static void testGetWorkItemHistoryNullId() {
        Test.startTest();
        try {
            WorkItemController.getWorkItemHistory(null);
